        let actual = data
            .iter()
            .enumerate()
            .fold((0u64, 0u64), |(s, w), (i, &v)| (s.wrapping_add(u64::from(v)), w.wrapping_add((i as u64 + 1).wrapping_mul(u64::from(v)))));
        assert_eq!(actual, (sum, weighted), "{name}: sensor samples differ from reference");
        seen += 1;
